export type AuthResponse = {
    status: string;
    data: Auth;
};

export type AuthToken = {
    token_key: string;
    readonly label: string;
    readonly expires: number;
    readonly created: number;
};

export type AuthTokenList = Array<AuthToken>;

export type AuthTokenListResponse = {
    status: string;
    data: AuthTokenList;
};

export type AuthTokenResponse = {
    status: string;
    data: AuthToken;
};

export type Authenticated = {
    /**
     * Fetch a token to use for authentication. The token is excluded if this
     * is a cookied based authenication response.
     */
    readonly token: string;
    /**
     * Fetch a refresh token to use for refreshing authentication. The refresh
     * token is excluded if this is a cookied based authenication response.
     */
    readonly refresh_token: string;
    user: ProtectedUserInfo;
    readonly challenges: Array<AuthenticatorChallenge>;
    readonly expires: number;
    readonly created: number;
};

export type AuthenticatedResponse = {
    status: string;
    data: Authenticated;
};

export type AuthenticatorChallenge = {
    readonly id: string;
    /**
     * * `authentication` - Authentication
     * * `authorization` - Authorization
     * * `setup` - Setup
     * * `external_authorization` - External Authorization
     */
    readonly type: 'authentication' | 'authorization' | 'setup' | 'external_authorization';
    /**
     * * `ephemeral` - Ephemeral
     * * `durable` - Durable
     * * `permanent` - Permanent
     */
    readonly durability: 'ephemeral' | 'durable' | 'permanent';
    readonly authenticator_types: Array<'totp' | 'sms' | 'static'>;
    readonly created: number;
};

